CREATE TABLE [sales].[CashDrawer]([CashDrawerId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_CashDrawer_Id] DEFAULT NEWSEQUENTIALID(),[ShiftId] UNIQUEIDENTIFIER NOT NULL,[EntryType] NVARCHAR(20) NOT NULL,[Amount] DECIMAL(18,2) NOT NULL,[ReferenceType] NVARCHAR(30) NULL,[ReferenceId] UNIQUEIDENTIFIER NULL,[Remarks] NVARCHAR(500) NULL,[CreatedBy] NVARCHAR(256) NULL,[CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_CashDrawer_Created] DEFAULT SYSUTCDATETIME(),CONSTRAINT [PK_CashDrawer] PRIMARY KEY([CashDrawerId]),CONSTRAINT [FK_CashDrawer_Shift] FOREIGN KEY([ShiftId]) REFERENCES [sales].[POSShift]([ShiftId]),CONSTRAINT [CK_CashDrawer_Type] CHECK([EntryType] IN('OPENING','SALE','REFUND','CASH_IN','CASH_OUT','CLOSING')));
